import{i as e,r as t,s as n,t as r}from"./app-Jqt1KknN.js";var i=JSON.parse(`{"path":"/guide/http-client/","title":"HTTP-клиент: внешние API","lang":"ru-RU","frontmatter":{"prev":"/guide/gin/best-practices.md","next":"/guide/http-client/tests.md"},"git":{"updatedTime":1791921728000,"contributors":[{"name":"Danil Chugaev","username":"","email":"danilchugaev@mail.ru","commits":1}],"changelog":[{"hash":"637963e3ed0a8ac446a62da3eb38da1714a829c6","time":1791921728000,"email":"danilchugaev@mail.ru","author":"Danil Chugaev","message":"chore: used local logo"}]},"filePathRelative":"guide/http-client/README.md"}`),a={name:`README.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="http-клиент-внешние-api" tabindex="-1"><a class="header-anchor" href="#http-клиент-внешние-api"><span>HTTP-клиент: внешние API</span></a></h1><h2 id="цель-урока" tabindex="-1"><a class="header-anchor" href="#цель-урока"><span>Цель урока</span></a></h2><p>Научиться вызывать внешний HTTP API через стандартный <code>http.Client</code>: строить request с <code>context.Context</code>, передавать query-параметры и заголовки, корректно закрывать response body, проверять HTTP-статус, декодировать JSON и тестировать клиент без реальной сети.</p><p>Task Manager API уже принимает запросы как HTTP-сервер. Backend часто выступает и клиентом: запрашивает данные у сервиса уведомлений, платежей, геокодирования или другого внутреннего API. В этой главе Task Manager обращается к условному внешнему сервису, чтобы получить подсказку приоритета для новой задачи.</p><h2 id="http-client-и-request" tabindex="-1"><a class="header-anchor" href="#http-client-и-request"><span><code>http.Client</code> и request</span></a></h2><p>Быстрый вызов можно сделать через <code>http.Get</code>, но для backend-кода обычно нужен явный <code>http.Client</code> и request:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">client <span class="token operator">:=</span> <span class="token operator">&amp;</span>http<span class="token punctuation">.</span>Client<span class="token punctuation">{</span></span>
<span class="line">	Timeout<span class="token punctuation">:</span> <span class="token number">3</span> <span class="token operator">*</span> time<span class="token punctuation">.</span>Second<span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">request<span class="token punctuation">,</span> err <span class="token operator">:=</span> http<span class="token punctuation">.</span><span class="token function">NewRequestWithContext</span><span class="token punctuation">(</span></span>
<span class="line">	ctx<span class="token punctuation">,</span></span>
<span class="line">	http<span class="token punctuation">.</span>MethodGet<span class="token punctuation">,</span></span>
<span class="line">	<span class="token string">&quot;https://priority.example.com/v1/suggest?title=Купить+молоко&quot;</span><span class="token punctuation">,</span></span>
<span class="line">	<span class="token boolean">nil</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> err</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">response<span class="token punctuation">,</span> err <span class="token operator">:=</span> client<span class="token punctuation">.</span><span class="token function">Do</span><span class="token punctuation">(</span>request<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> err</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">defer</span> response<span class="token punctuation">.</span>Body<span class="token punctuation">.</span><span class="token function">Close</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>http.Client</code> можно безопасно переиспользовать между запросами и goroutine. Создавайте его один раз при сборке приложения и передавайте как зависимость. Создание нового <code>http.Client</code> на каждый вызов мешает переиспользованию соединений.</p><p><code>http.NewRequestWithContext</code> связывает запрос со стандартным <code>context.Context</code>. Если входящий запрос Task Manager отменён, внешний вызов тоже должен завершиться:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">hint<span class="token punctuation">,</span> err <span class="token operator">:=</span> priorityClient<span class="token punctuation">.</span><span class="token function">Suggest</span><span class="token punctuation">(</span>c<span class="token punctuation">.</span>Request<span class="token punctuation">.</span><span class="token function">Context</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> title<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Не создавайте внутри клиента новый <code>context.Background()</code>: так отмена и дедлайн потеряются.</p><h2 id="таимаут-клиента-и-дедлаин-context" tabindex="-1"><a class="header-anchor" href="#таимаут-клиента-и-дедлаин-context"><span>Таймаут клиента и дедлайн context</span></a></h2><p>У HTTP-вызова может быть два ограничения по времени:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">client <span class="token operator">:=</span> <span class="token operator">&amp;</span>http<span class="token punctuation">.</span>Client<span class="token punctuation">{</span>Timeout<span class="token punctuation">:</span> <span class="token number">3</span> <span class="token operator">*</span> time<span class="token punctuation">.</span>Second<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">ctx<span class="token punctuation">,</span> cancel <span class="token operator">:=</span> context<span class="token punctuation">.</span><span class="token function">WithTimeout</span><span class="token punctuation">(</span>parentCtx<span class="token punctuation">,</span> <span class="token number">1</span><span class="token operator">*</span>time<span class="token punctuation">.</span>Second<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">defer</span> <span class="token function">cancel</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><code>ctx</code> задаёт дедлайн <strong>конкретной операции</strong> и наследует отмену родителя;</li><li><code>Client.Timeout</code> — предельное время всей HTTP-операции клиента: соединения, редиректы и чтения body.</li></ul><p>В Task Manager передавайте входящий <code>r.Context()</code> и настройте общий ограниченный <code>Client.Timeout</code>. Если для конкретной зависимости нужен более короткий дедлайн, создайте дочерний context от полученного родителя. Всегда вызывайте <code>cancel</code>.</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">ctx<span class="token punctuation">,</span> cancel <span class="token operator">:=</span> context<span class="token punctuation">.</span><span class="token function">WithTimeout</span><span class="token punctuation">(</span>parentCtx<span class="token punctuation">,</span> <span class="token number">800</span><span class="token operator">*</span>time<span class="token punctuation">.</span>Millisecond<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">defer</span> <span class="token function">cancel</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">hint<span class="token punctuation">,</span> err <span class="token operator">:=</span> priorityClient<span class="token punctuation">.</span><span class="token function">Suggest</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> title<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Таймаут — не замена отмене: он ограничивает время, но код всё равно должен возвращать ошибку вызывающему слою. Не подбирайте таймауты «на глаз» для тестов; тесты этой главы не ждут реальные секунды.</p><h2 id="контракт-внешнего-сервиса" tabindex="-1"><a class="header-anchor" href="#контракт-внешнего-сервиса"><span>Контракт внешнего сервиса</span></a></h2><p>Пусть сервис подсказок поддерживает запрос:</p><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http"><pre><code class="language-http"><span class="line"><span class="token request-line"><span class="token method property">GET</span> <span class="token request-target url">/v1/suggest?title=%D0%9A%D1%83%D0%BF%D0%B8%D1%82%D1%8C+%D0%BC%D0%BE%D0%BB%D0%BE%D0%BA%D0%BE</span> <span class="token http-version property">HTTP/1.1</span></span></span>
<span class="line"><span class="token header"><span class="token header-name keyword">Accept</span><span class="token punctuation">:</span> <span class="token header-value">application/json</span></span></span>
<span class="line"><span class="token header"><span class="token header-name keyword">User-Agent</span><span class="token punctuation">:</span> <span class="token header-value">task-manager-api/1.0</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>И отвечает:</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;priority&quot;</span><span class="token operator">:</span> <span class="token number">3</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;source&quot;</span><span class="token operator">:</span> <span class="token string">&quot;title-rules&quot;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Внешний контракт не принадлежит нашей модели <code>Task</code>, поэтому выделим отдельный тип:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> PriorityHint <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	Priority <span class="token builtin">int</span>    <span class="token string">\`json:&quot;priority&quot;\`</span></span>
<span class="line">	Source   <span class="token builtin">string</span> <span class="token string">\`json:&quot;source&quot;\`</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Не декодируйте ответ внешнего API напрямую в <code>task.Task</code>: внешний сервис не должен иметь возможности задавать ID, completed или другие поля нашей предметной модели.</p><h2 id="клиент-как-зависимость" tabindex="-1"><a class="header-anchor" href="#клиент-как-зависимость"><span>Клиент как зависимость</span></a></h2><p>Спрячем детали HTTP в пакете <code>internal/priorityclient</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> Client <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	baseURL    <span class="token builtin">string</span></span>
<span class="line">	httpClient <span class="token operator">*</span>http<span class="token punctuation">.</span>Client</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">New</span><span class="token punctuation">(</span>baseURL <span class="token builtin">string</span><span class="token punctuation">,</span> httpClient <span class="token operator">*</span>http<span class="token punctuation">.</span>Client<span class="token punctuation">)</span> <span class="token operator">*</span>Client <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">if</span> httpClient <span class="token operator">==</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		httpClient <span class="token operator">=</span> <span class="token operator">&amp;</span>http<span class="token punctuation">.</span>Client<span class="token punctuation">{</span>Timeout<span class="token punctuation">:</span> <span class="token number">3</span> <span class="token operator">*</span> time<span class="token punctuation">.</span>Second<span class="token punctuation">}</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> <span class="token operator">&amp;</span>Client<span class="token punctuation">{</span></span>
<span class="line">		baseURL<span class="token punctuation">:</span>    strings<span class="token punctuation">.</span><span class="token function">TrimRight</span><span class="token punctuation">(</span>baseURL<span class="token punctuation">,</span> <span class="token string">&quot;/&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">		httpClient<span class="token punctuation">:</span> httpClient<span class="token punctuation">,</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>baseURL</code> и <code>httpClient</code> передаются снаружи: production использует адрес из конфигурации, а тест — адрес <code>httptest.Server</code>. Так тест не обращается к интернету.</p><h2 id="безопасная-сборка-url" tabindex="-1"><a class="header-anchor" href="#безопасная-сборка-url"><span>Безопасная сборка URL</span></a></h2><p>Не добавляйте пользовательский текст к URL конкатенацией строк:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token comment">// Плохо: пробелы, &amp;, ? и кириллица могут сломать запрос.</span></span>
<span class="line"><span class="token comment">// endpoint := baseURL + &quot;/v1/suggest?title=&quot; + title</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>Используйте <code>net/url</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">endpoint<span class="token punctuation">,</span> err <span class="token operator">:=</span> url<span class="token punctuation">.</span><span class="token function">Parse</span><span class="token punctuation">(</span>client<span class="token punctuation">.</span>baseURL <span class="token operator">+</span> <span class="token string">&quot;/v1/suggest&quot;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> PriorityHint<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;разобрать URL сервиса приоритетов: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">query <span class="token operator">:=</span> endpoint<span class="token punctuation">.</span><span class="token function">Query</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">query<span class="token punctuation">.</span><span class="token function">Set</span><span class="token punctuation">(</span><span class="token string">&quot;title&quot;</span><span class="token punctuation">,</span> title<span class="token punctuation">)</span></span>
<span class="line">endpoint<span class="token punctuation">.</span>RawQuery <span class="token operator">=</span> query<span class="token punctuation">.</span><span class="token function">Encode</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>query.Encode()</code> экранирует специальные символы. Например, название <code>Позвонить маме &amp; купить чай</code> будет передано одним параметром <code>title</code>, а не превратится в несколько query-параметров.</p><h2 id="полная-реализация-suggest" tabindex="-1"><a class="header-anchor" href="#полная-реализация-suggest"><span>Полная реализация <code>Suggest</code></span></a></h2><p>Опишем ошибку неуспешного HTTP-статуса отдельно. Вызывающий код может проверить её через <code>errors.As</code> и решить, стоит ли повторять запрос или вернуть пользователю другой ответ:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> HTTPStatusError <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	StatusCode <span class="token builtin">int</span></span>
<span class="line">	Status     <span class="token builtin">string</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>err <span class="token operator">*</span>HTTPStatusError<span class="token punctuation">)</span> <span class="token function">Error</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token builtin">string</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> fmt<span class="token punctuation">.</span><span class="token function">Sprintf</span><span class="token punctuation">(</span><span class="token string">&quot;сервис приоритетов вернул %s&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">.</span>Status<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Реализация клиента:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">const</span> maxResponseBytes <span class="token operator">=</span> <span class="token number">1</span> <span class="token operator">&lt;&lt;</span> <span class="token number">20</span> <span class="token comment">// 1 MiB</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>client <span class="token operator">*</span>Client<span class="token punctuation">)</span> <span class="token function">Suggest</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> title <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">(</span>PriorityHint<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	endpoint<span class="token punctuation">,</span> err <span class="token operator">:=</span> url<span class="token punctuation">.</span><span class="token function">Parse</span><span class="token punctuation">(</span>client<span class="token punctuation">.</span>baseURL <span class="token operator">+</span> <span class="token string">&quot;/v1/suggest&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> PriorityHint<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;разобрать URL сервиса приоритетов: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	query <span class="token operator">:=</span> endpoint<span class="token punctuation">.</span><span class="token function">Query</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	query<span class="token punctuation">.</span><span class="token function">Set</span><span class="token punctuation">(</span><span class="token string">&quot;title&quot;</span><span class="token punctuation">,</span> title<span class="token punctuation">)</span></span>
<span class="line">	endpoint<span class="token punctuation">.</span>RawQuery <span class="token operator">=</span> query<span class="token punctuation">.</span><span class="token function">Encode</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	request<span class="token punctuation">,</span> err <span class="token operator">:=</span> http<span class="token punctuation">.</span><span class="token function">NewRequestWithContext</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> http<span class="token punctuation">.</span>MethodGet<span class="token punctuation">,</span> endpoint<span class="token punctuation">.</span><span class="token function">String</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token boolean">nil</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> PriorityHint<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;создать запрос подсказки: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	request<span class="token punctuation">.</span>Header<span class="token punctuation">.</span><span class="token function">Set</span><span class="token punctuation">(</span><span class="token string">&quot;Accept&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;application/json&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	request<span class="token punctuation">.</span>Header<span class="token punctuation">.</span><span class="token function">Set</span><span class="token punctuation">(</span><span class="token string">&quot;User-Agent&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;task-manager-api/1.0&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	response<span class="token punctuation">,</span> err <span class="token operator">:=</span> client<span class="token punctuation">.</span>httpClient<span class="token punctuation">.</span><span class="token function">Do</span><span class="token punctuation">(</span>request<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> PriorityHint<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;выполнить запрос подсказки: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">defer</span> response<span class="token punctuation">.</span>Body<span class="token punctuation">.</span><span class="token function">Close</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> response<span class="token punctuation">.</span>StatusCode <span class="token operator">&lt;</span> http<span class="token punctuation">.</span>StatusOK <span class="token operator">||</span> response<span class="token punctuation">.</span>StatusCode <span class="token operator">&gt;=</span> http<span class="token punctuation">.</span>StatusMultipleChoices <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> PriorityHint<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>HTTPStatusError<span class="token punctuation">{</span></span>
<span class="line">			StatusCode<span class="token punctuation">:</span> response<span class="token punctuation">.</span>StatusCode<span class="token punctuation">,</span></span>
<span class="line">			Status<span class="token punctuation">:</span>     response<span class="token punctuation">.</span>Status<span class="token punctuation">,</span></span>
<span class="line">		<span class="token punctuation">}</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">var</span> hint PriorityHint</span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">NewDecoder</span><span class="token punctuation">(</span>io<span class="token punctuation">.</span><span class="token function">LimitReader</span><span class="token punctuation">(</span>response<span class="token punctuation">.</span>Body<span class="token punctuation">,</span> maxResponseBytes<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Decode</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>hint<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> PriorityHint<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;прочитать JSON-подсказку: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">if</span> hint<span class="token punctuation">.</span>Priority <span class="token operator">&lt;</span> <span class="token number">1</span> <span class="token operator">||</span> hint<span class="token punctuation">.</span>Priority <span class="token operator">&gt;</span> <span class="token number">5</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> PriorityHint<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;некорректный приоритет внешнего сервиса: %d&quot;</span><span class="token punctuation">,</span> hint<span class="token punctuation">.</span>Priority<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> hint<span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Ключевой порядок действий:</p><ol><li><code>Do</code> вернул response — сразу планируем <code>defer response.Body.Close()</code>;</li><li>проверяем статус <strong>до</strong> разбора JSON успеха;</li><li>ограничиваем размер читаемого response body;</li><li>декодируем в отдельный внешний DTO;</li><li>проверяем данные внешней системы, даже если ответ имеет статус <code>2xx</code>.</li></ol><p><code>response.Body.Close()</code> важен даже при ошибочном статусе: он освобождает ресурс и позволяет клиенту переиспользовать соединения.</p><h2 id="проверка-статусов-и-ошибки-сети" tabindex="-1"><a class="header-anchor" href="#проверка-статусов-и-ошибки-сети"><span>Проверка статусов и ошибки сети</span></a></h2><p>HTTP-клиент не считает <code>404</code>, <code>429</code> или <code>500</code> ошибкой транспорта: в этих случаях <code>client.Do</code> обычно вернёт <code>response</code> и <code>nil</code> error. Поэтому статус нужно проверять самостоятельно.</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">if</span> response<span class="token punctuation">.</span>StatusCode <span class="token operator">&lt;</span> <span class="token number">200</span> <span class="token operator">||</span> response<span class="token punctuation">.</span>StatusCode <span class="token operator">&gt;=</span> <span class="token number">300</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> PriorityHint<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>HTTPStatusError<span class="token punctuation">{</span><span class="token operator">...</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Транспортная ошибка — это, например, отмена context, проблема DNS или недоступное соединение. Она приходит из <code>Do</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">response<span class="token punctuation">,</span> err <span class="token operator">:=</span> client<span class="token punctuation">.</span>httpClient<span class="token punctuation">.</span><span class="token function">Do</span><span class="token punctuation">(</span>request<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">if</span> errors<span class="token punctuation">.</span><span class="token function">Is</span><span class="token punctuation">(</span>err<span class="token punctuation">,</span> context<span class="token punctuation">.</span>Canceled<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> PriorityHint<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> err</span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> PriorityHint<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> fmt<span class="token punctuation">.</span><span class="token function">Errorf</span><span class="token punctuation">(</span><span class="token string">&quot;выполнить запрос подсказки: %w&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>На границе HTTP handler не превращайте все ошибки клиента во внутренний <code>500</code> автоматически. Например, отменённый клиентский запрос обычно уже не ждёт ответ; ограничение внешнего сервиса может требовать понятной политики. В этой главе client только возвращает причины, а решение о публичном HTTP-статусе остаётся за service или handler.</p><h2 id="заголовки" tabindex="-1"><a class="header-anchor" href="#заголовки"><span>Заголовки</span></a></h2><p>Заголовки передают метаданные запроса:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">request<span class="token punctuation">.</span>Header<span class="token punctuation">.</span><span class="token function">Set</span><span class="token punctuation">(</span><span class="token string">&quot;Accept&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;application/json&quot;</span><span class="token punctuation">)</span></span>
<span class="line">request<span class="token punctuation">.</span>Header<span class="token punctuation">.</span><span class="token function">Set</span><span class="token punctuation">(</span><span class="token string">&quot;Authorization&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;Bearer &quot;</span><span class="token operator">+</span>token<span class="token punctuation">)</span></span>
<span class="line">request<span class="token punctuation">.</span>Header<span class="token punctuation">.</span><span class="token function">Set</span><span class="token punctuation">(</span><span class="token string">&quot;X-Request-ID&quot;</span><span class="token punctuation">,</span> requestID<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><code>Accept</code> сообщает ожидаемый формат ответа;</li><li><code>Authorization</code> используют только при необходимости и получают token из конфигурации, а не из исходного кода;</li><li><code>X-Request-ID</code> связывает логи нескольких сервисов.</li></ul><p>Не записывайте <code>Authorization</code>, cookies и полный body в логи. Если копируете входящий request ID во внешний запрос, сначала извлеките и проверьте его по правилам middleware из предыдущей главы.</p><h2 id="где-вызывать-внешнии-клиент" tabindex="-1"><a class="header-anchor" href="#где-вызывать-внешнии-клиент"><span>Где вызывать внешний клиент</span></a></h2><p>HTTP handler не должен сам знать URL внешнего сервиса. Пусть service получает интерфейс:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> PrioritySuggester <span class="token keyword">interface</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token function">Suggest</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> title <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">(</span>priorityclient<span class="token punctuation">.</span>PriorityHint<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> TaskService <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	store     TaskRepository</span>
<span class="line">	priorities PrioritySuggester</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>При создании задачи service может применить подсказку, если пользователь не выбрал приоритет сам. Политику нужно определить явно: внешний сервис недоступен — создание задачи завершается ошибкой или используется приоритет по умолчанию? Для первого учебного API выберите один вариант и закрепите его тестом. Не скрывайте ошибку молча.</p><h2 id="тестирование-через-httptest-server" tabindex="-1"><a class="header-anchor" href="#тестирование-через-httptest-server"><span>Тестирование через <code>httptest.Server</code></span></a></h2><p><code>httptest.Server</code> запускает настоящий HTTP-сервер только внутри теста и автоматически предоставляет адрес. Снаружи сеть не используется:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">TestSuggest</span><span class="token punctuation">(</span>t <span class="token operator">*</span>testing<span class="token punctuation">.</span>T<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	server <span class="token operator">:=</span> httptest<span class="token punctuation">.</span><span class="token function">NewServer</span><span class="token punctuation">(</span>http<span class="token punctuation">.</span><span class="token function">HandlerFunc</span><span class="token punctuation">(</span><span class="token keyword">func</span><span class="token punctuation">(</span>w http<span class="token punctuation">.</span>ResponseWriter<span class="token punctuation">,</span> r <span class="token operator">*</span>http<span class="token punctuation">.</span>Request<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">if</span> r<span class="token punctuation">.</span>Method <span class="token operator">!=</span> http<span class="token punctuation">.</span>MethodGet <span class="token punctuation">{</span></span>
<span class="line">			t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;method = %s, ожидался GET&quot;</span><span class="token punctuation">,</span> r<span class="token punctuation">.</span>Method<span class="token punctuation">)</span></span>
<span class="line">		<span class="token punctuation">}</span></span>
<span class="line">		<span class="token keyword">if</span> got <span class="token operator">:=</span> r<span class="token punctuation">.</span>URL<span class="token punctuation">.</span><span class="token function">Query</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Get</span><span class="token punctuation">(</span><span class="token string">&quot;title&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> got <span class="token operator">!=</span> <span class="token string">&quot;Купить молоко&quot;</span> <span class="token punctuation">{</span></span>
<span class="line">			t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;title = %q&quot;</span><span class="token punctuation">,</span> got<span class="token punctuation">)</span></span>
<span class="line">		<span class="token punctuation">}</span></span>
<span class="line">		<span class="token keyword">if</span> got <span class="token operator">:=</span> r<span class="token punctuation">.</span>Header<span class="token punctuation">.</span><span class="token function">Get</span><span class="token punctuation">(</span><span class="token string">&quot;Accept&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> got <span class="token operator">!=</span> <span class="token string">&quot;application/json&quot;</span> <span class="token punctuation">{</span></span>
<span class="line">			t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;Accept = %q&quot;</span><span class="token punctuation">,</span> got<span class="token punctuation">)</span></span>
<span class="line">		<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">		w<span class="token punctuation">.</span><span class="token function">Header</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Set</span><span class="token punctuation">(</span><span class="token string">&quot;Content-Type&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;application/json&quot;</span><span class="token punctuation">)</span></span>
<span class="line">		fmt<span class="token punctuation">.</span><span class="token function">Fprint</span><span class="token punctuation">(</span>w<span class="token punctuation">,</span> <span class="token string">\`{&quot;priority&quot;:3,&quot;source&quot;:&quot;title-rules&quot;}\`</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">defer</span> server<span class="token punctuation">.</span><span class="token function">Close</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	client <span class="token operator">:=</span> <span class="token function">New</span><span class="token punctuation">(</span>server<span class="token punctuation">.</span>URL<span class="token punctuation">,</span> server<span class="token punctuation">.</span><span class="token function">Client</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	hint<span class="token punctuation">,</span> err <span class="token operator">:=</span> client<span class="token punctuation">.</span><span class="token function">Suggest</span><span class="token punctuation">(</span>context<span class="token punctuation">.</span><span class="token function">Background</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token string">&quot;Купить молоко&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;Suggest вернул ошибку: %v&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">if</span> hint <span class="token operator">!=</span> <span class="token punctuation">(</span>PriorityHint<span class="token punctuation">{</span>Priority<span class="token punctuation">:</span> <span class="token number">3</span><span class="token punctuation">,</span> Source<span class="token punctuation">:</span> <span class="token string">&quot;title-rules&quot;</span><span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;hint = %+v&quot;</span><span class="token punctuation">,</span> hint<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Проверяйте контракт исходящего запроса: метод, путь, query и существенные заголовки. Затем проверяйте, как клиент обработал ответ.</p><h3 id="неуспешныи-статус" tabindex="-1"><a class="header-anchor" href="#неуспешныи-статус"><span>Неуспешный статус</span></a></h3><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">TestSuggestStatusError</span><span class="token punctuation">(</span>t <span class="token operator">*</span>testing<span class="token punctuation">.</span>T<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	server <span class="token operator">:=</span> httptest<span class="token punctuation">.</span><span class="token function">NewServer</span><span class="token punctuation">(</span>http<span class="token punctuation">.</span><span class="token function">HandlerFunc</span><span class="token punctuation">(</span><span class="token keyword">func</span><span class="token punctuation">(</span>w http<span class="token punctuation">.</span>ResponseWriter<span class="token punctuation">,</span> r <span class="token operator">*</span>http<span class="token punctuation">.</span>Request<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		w<span class="token punctuation">.</span><span class="token function">WriteHeader</span><span class="token punctuation">(</span>http<span class="token punctuation">.</span>StatusTooManyRequests<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">defer</span> server<span class="token punctuation">.</span><span class="token function">Close</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	client <span class="token operator">:=</span> <span class="token function">New</span><span class="token punctuation">(</span>server<span class="token punctuation">.</span>URL<span class="token punctuation">,</span> server<span class="token punctuation">.</span><span class="token function">Client</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token boolean">_</span><span class="token punctuation">,</span> err <span class="token operator">:=</span> client<span class="token punctuation">.</span><span class="token function">Suggest</span><span class="token punctuation">(</span>context<span class="token punctuation">.</span><span class="token function">Background</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token string">&quot;Купить молоко&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">var</span> statusError <span class="token operator">*</span>HTTPStatusError</span>
<span class="line">	<span class="token keyword">if</span> <span class="token operator">!</span>errors<span class="token punctuation">.</span><span class="token function">As</span><span class="token punctuation">(</span>err<span class="token punctuation">,</span> <span class="token operator">&amp;</span>statusError<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;error = %v, ожидалась HTTPStatusError&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">if</span> statusError<span class="token punctuation">.</span>StatusCode <span class="token operator">!=</span> http<span class="token punctuation">.</span>StatusTooManyRequests <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;status = %d&quot;</span><span class="token punctuation">,</span> statusError<span class="token punctuation">.</span>StatusCode<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="отмена-без-time-sleep" tabindex="-1"><a class="header-anchor" href="#отмена-без-time-sleep"><span>Отмена без <code>time.Sleep</code></span></a></h3><p>Чтобы детерминированно проверить связь request и context, отмените context <strong>до</strong> вызова. Клиент не должен пытаться ждать ответ:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">TestSuggestCanceled</span><span class="token punctuation">(</span>t <span class="token operator">*</span>testing<span class="token punctuation">.</span>T<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	server <span class="token operator">:=</span> httptest<span class="token punctuation">.</span><span class="token function">NewServer</span><span class="token punctuation">(</span>http<span class="token punctuation">.</span><span class="token function">NotFoundHandler</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">defer</span> server<span class="token punctuation">.</span><span class="token function">Close</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	ctx<span class="token punctuation">,</span> cancel <span class="token operator">:=</span> context<span class="token punctuation">.</span><span class="token function">WithCancel</span><span class="token punctuation">(</span>context<span class="token punctuation">.</span><span class="token function">Background</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token function">cancel</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	client <span class="token operator">:=</span> <span class="token function">New</span><span class="token punctuation">(</span>server<span class="token punctuation">.</span>URL<span class="token punctuation">,</span> server<span class="token punctuation">.</span><span class="token function">Client</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token boolean">_</span><span class="token punctuation">,</span> err <span class="token operator">:=</span> client<span class="token punctuation">.</span><span class="token function">Suggest</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> <span class="token string">&quot;Купить молоко&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> <span class="token operator">!</span>errors<span class="token punctuation">.</span><span class="token function">Is</span><span class="token punctuation">(</span>err<span class="token punctuation">,</span> context<span class="token punctuation">.</span>Canceled<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;error = %v, ожидалась context.Canceled&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Тест не использует настоящую задержку и не зависит от доступности публичного сервиса.</p><h2 id="повторы-запросов" tabindex="-1"><a class="header-anchor" href="#повторы-запросов"><span>Повторы запросов</span></a></h2><p>Не добавляйте автоматические retry «на всякий случай». Повтор может создать дубликат для <code>POST</code>, усилить нагрузку на недоступный сервис и ухудшить ситуацию при <code>429</code>.</p><p>Для идемпотентного <code>GET</code> повтор иногда оправдан после временной сетевой ошибки, но только с ограничением числа попыток, backoff, учётом context и понятной политикой. Эти сценарии относятся к более продвинутой production-надёжности; базовый клиент этой главы делает одну прозрачную попытку.</p><h2 id="частые-ошибки" tabindex="-1"><a class="header-anchor" href="#частые-ошибки"><span>Частые ошибки</span></a></h2><h3 id="не-закрывать-response-body" tabindex="-1"><a class="header-anchor" href="#не-закрывать-response-body"><span>Не закрывать response body</span></a></h3><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">response<span class="token punctuation">,</span> err <span class="token operator">:=</span> client<span class="token punctuation">.</span><span class="token function">Do</span><span class="token punctuation">(</span>request<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> err</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Пропущен response.Body.Close().</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Это может истощить ресурсы и лишить клиента переиспользования соединений. Сразу после успешного <code>Do</code> пишите <code>defer response.Body.Close()</code>.</p><h3 id="декодировать-ошибочныи-ответ-как-успешныи-json" tabindex="-1"><a class="header-anchor" href="#декодировать-ошибочныи-ответ-как-успешныи-json"><span>Декодировать ошибочный ответ как успешный JSON</span></a></h3><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">json<span class="token punctuation">.</span><span class="token function">NewDecoder</span><span class="token punctuation">(</span>response<span class="token punctuation">.</span>Body<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Decode</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>hint<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Сначала проверяйте статус. Сервер может прислать JSON другого формата, HTML или пустое тело с <code>404</code> и <code>500</code>.</p><h3 id="создать-новыи-context-внутри-клиента" tabindex="-1"><a class="header-anchor" href="#создать-новыи-context-внутри-клиента"><span>Создать новый context внутри клиента</span></a></h3><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">request<span class="token punctuation">,</span> <span class="token boolean">_</span> <span class="token operator">:=</span> http<span class="token punctuation">.</span><span class="token function">NewRequestWithContext</span><span class="token punctuation">(</span>context<span class="token punctuation">.</span><span class="token function">Background</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token operator">...</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Так отмена исходной операции не дойдёт до внешнего запроса. Получайте <code>ctx</code> параметром.</p><h3 id="тестировать-публичныи-сервис" tabindex="-1"><a class="header-anchor" href="#тестировать-публичныи-сервис"><span>Тестировать публичный сервис</span></a></h3><p>Публичный сервис может быть недоступен, изменить контракт или ограничить число запросов. Для unit-тестов используйте <code>httptest.Server</code>; реальную интеграцию проверяйте отдельно и осознанно.</p><h2 id="дальше" tabindex="-1"><a class="header-anchor" href="#дальше"><span>Дальше</span></a></h2><p>Task Manager умеет безопасно вызывать внешние API. Далее настроим конфигурацию и жизненный цикл приложения: переменные окружения, проверку настроек, graceful shutdown и health-check.</p>`,86)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};